import type { TextProps } from '@/shared/types';

// Title Studio template catalogue. A template is a partial TextProps on top of
// TEMPLATE_BASE (so applying one resets every style field), plus an optional vertical
// offset, scene background, clip duration and placeholder content.
//
// Studio / movie templates are *evocations* in the spirit of the originals (fonts,
// colours, motion) built from the app's own effects — the user puts their own word in.

export type TemplateCategory = 'studio' | 'movies' | 'party' | 'creators' | 'retro' | 'modern' | 'nature' | 'basic';

export interface TitleTemplate {
  id: string;
  label: string;
  emoji: string;
  category: TemplateCategory;
  hint: string;
  text: Partial<TextProps>;
  /** Vertical offset as a fraction of the frame height (0 = centre). */
  y?: number;
  /** Scene (project) background to set when applied. */
  bg?: string;
  /** Clip duration to set (whole-clip animations, logo intros). */
  duration?: number;
  /** Placeholder text, used when the clip still has the default text. */
  content?: string;
}

export const TEMPLATE_CATEGORIES: { id: TemplateCategory | 'all'; label: string }[] = [
  { id: 'all', label: 'All' }, { id: 'studio', label: '🎬 Studio intros' }, { id: 'movies', label: '🍿 Movies & TV' }, { id: 'party', label: '🪩 Party' },
  { id: 'creators', label: '📺 Creators' }, { id: 'retro', label: '📼 Retro' }, { id: 'modern', label: '✨ Modern' }, { id: 'nature', label: '🌿 Nature' }, { id: 'basic', label: '🔤 Basic' },
];

/** Neutral style every template starts from (fields a template does not mention are reset to these). */
export const TEMPLATE_BASE: Partial<TextProps> = {
  fontFamily: 'Segoe UI', fontSize: 110, bold: true, italic: false, color: '#ffffff', align: 'center', lineHeight: 1.2,
  background: '', backgroundPadding: 24, shadow: false, outline: '', outlineWidth: 0.06,
  animation: 'fade', animationDuration: 0.8, exitAnimation: 'fade', exitDuration: 0.6, letterSpacing: 0, boxWidth: 0.9,
  glow: 0, glowColor: '#ffffff', backdrop: 'none', backdropColor: '#000000', backdropColor2: '#1a237e', layout: 'block', perspective: 0.6,
  fill: 'solid', fillColor2: '#888888', extrude: 0, extrudeColor: '#222222', offsetY: 0,
};

/** Full style of a template (base + overrides). */
export const templateStyle = (tpl: TitleTemplate): Partial<TextProps> => ({ ...TEMPLATE_BASE, ...tpl.text });

const T = (id: string, label: string, emoji: string, category: TemplateCategory, hint: string, text: Partial<TextProps>, extra: Partial<Pick<TitleTemplate, 'y' | 'bg' | 'duration' | 'content'>> = {}): TitleTemplate =>
  ({ id, label, emoji, category, hint, text, ...extra });

